-- +goose Up
CREATE TYPE damage_class AS ENUM (
	'PHYSICAL',
	'SPECIAL',
	'STATUS'
);

CREATE TYPE elemental_type AS ENUM (
	'GRASS',
	'FIRE',
	'WATER',
	'ELECTRIC',
	'ROCK',
	'GROUND',
	'FLYING',
	'PSYCHIC',
	'GHOST',
	'POISON',
	'FIGHTING',
	'DARK',
	'STEEL',
	'FAIRY',
	'BUG',
	'ICE',
	'DRAGON',
	'NORMAL'
);

CREATE TABLE "pokemon" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"type1" elemental_type NOT NULL,
	"type2" elemental_type,
	"base_hp" SMALLINT NOT NULL,
	"base_atk" SMALLINT NOT NULL,
	"base_def" SMALLINT NOT NULL,
	"base_spatk" SMALLINT NOT NULL,
	"base_spdef" SMALLINT NOT NULL,
	"base_speed" SMALLINT NOT NULL,
	"order" INTEGER NOT NULL,
	"height" SMALLINT,
	"weight" SMALLINT,
	PRIMARY KEY("id")
);

CREATE TABLE "ability" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"effect" TEXT NOT NULL,
	"effect_short" TEXT,
	"gen_introduced" SMALLINT,
	PRIMARY KEY("id")
);

CREATE TABLE "pokemon_ability" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"pokemon_id" INTEGER NOT NULL,
	"ability_id" INTEGER NOT NULL,
	"slot" SMALLINT NOT NULL,
	"generation" SMALLINT,
	PRIMARY KEY("id"),
	CONSTRAINT pokemon_ability_slot_unique UNIQUE NULLS NOT DISTINCT ("pokemon_id", "slot", "generation")
);

CREATE TABLE "move" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	"accuracy" SMALLINT,
	"effect_chance" SMALLINT,
	"pp" SMALLINT NOT NULL,
	"priority" SMALLINT NOT NULL CHECK(priority BETWEEN -8 AND 8),
	"power" SMALLINT NOT NULL DEFAULT 0,
	"damage_class" damage_class NOT NULL,
	"effect" TEXT,
	"ailment_id" INTEGER,
	"move_category_id" INTEGER,
	"min_hits" SMALLINT,
	"max_hits" SMALLINT,
	"min_turns" SMALLINT,
	"max_turns" SMALLINT,
	"drain" SMALLINT,
	"healing" SMALLINT,
	"crit_rate" SMALLINT,
	"ailment_chance" SMALLINT,
	"flinch_chance" SMALLINT,
	"stat_chance" SMALLINT,
	"stat_changes" JSONB,
	"target" INTEGER,
	"type" elemental_type,
	PRIMARY KEY("id")
);

CREATE TABLE "ailment" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255) NOT NULL,
	"effect" TEXT NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE "move_category" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	"description" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE "move_target" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	"description" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE "item" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(255),
	"fling_power" SMALLINT,
	"fling_effect" TEXT,
	"category" VARCHAR(255) NOT NULL,
	-- might just need to filter on this in pokeapi on ingestion
	"attribute" VARCHAR(255),
	"effect" TEXT NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON COLUMN "item"."attribute" IS 'might just need to filter on this in pokeapi on ingestion';

ALTER TABLE "pokemon_ability"
ADD CONSTRAINT pokemon_ability_ability_fk FOREIGN KEY("ability_id") REFERENCES "ability"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "pokemon_ability"
ADD CONSTRAINT pokemon_ability_pokemon_fk FOREIGN KEY("pokemon_id") REFERENCES "pokemon"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "move"
ADD FOREIGN KEY("ailment_id") REFERENCES "ailment"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "move"
ADD FOREIGN KEY("move_category_id") REFERENCES "move_category"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "move"
ADD FOREIGN KEY("target") REFERENCES "move_target"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;

-- +goose Down
DROP TABLE "pokemon_ability";
DROP TABLE "move";
DROP TABLE "item";
DROP TABLE "move_target";
DROP TABLE "move_category";
DROP TABLE "ailment";
DROP TABLE "ability";
DROP TABLE "pokemon";
DROP TYPE elemental_type;
DROP TYPE damage_class;
